//! A guest that signs, linked by the runtime itself.
//!
//! `enclave:signer` is wired by hand in `signer::add_to_linker`, and a guest's imports are
//! generated by wit-bindgen from the runtime's own `wit/` (the `enclave-wit` crate). wasmtime
//! checks every import's name and type when it links a component, so an enclave that starts on
//! `examples/guest-signer` is one whose wiring matches what a guest calls. What the calls do is
//! `wallet`'s unit tests'; a whole signature through this guest is the client library's
//! (`clients/react-native/rust/vtxos-client/tests/sign.rs`).
//!
//! ```console
//! $ scripts/build-guest.sh signer
//! $ cargo test -p enclave-runtime --test signer_guest -- --ignored
//! ```

use enclave_runtime::testing::Enclave;

fn guest() -> Vec<u8> {
    let path = std::env::var_os("GUEST_SIGNER_WASM")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../examples/guest-signer/target/wasm32-wasip2/release/guest-signer.wasm")
        });
    std::fs::read(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; scripts/build-guest.sh signer", path.display()))
}

#[tokio::test]
#[ignore = "needs examples/guest-signer built for wasm32-wasip2"]
async fn the_signer_guest_links_against_the_runtime() {
    Enclave::builder(guest())
        .start()
        .await
        .expect("the runtime links every import the signer guest makes");
}
